  asScan: () => { const tag = (v('asScan') || '').trim().toUpperCase().replace(/^MSEA-AS\|/, ''); if (!tag) return toast('Enter or scan an asset tag.', 'bad'); const a = AT().assets.find(x => x.tag.toUpperCase() === tag || x.serial.toUpperCase() === tag || x.rfid && x.rfid.toUpperCase() === tag); if (!a) return toast('No asset with tag ' + tag + '.', 'bad'); if (!asVisible(a)) return toast('That asset is outside your data scope.', 'bad'); audit('Asset Management', 'Asset scanned', { new: a.tag }); asOpen(a.id); },
