  asFm: t => { App.ui.asF = Object.assign({}, App.ui.asF || {}, { [t.dataset.k]: [...t.selectedOptions].map(o => o.value) }); rerender(); },
  asFAll: t => { const k = t.dataset.k, all = t.dataset.v === '1'; const vals = k === 'br' ? (AS_CORP() ? ['CORP'] : []).concat(DATA.branches.filter(b => !b.closed && pcScopeBr().has(b.id)).map(b => b.id)) : AM().rooms.slice(); App.ui.asF = Object.assign({}, App.ui.asF || {}, { [k]: all ? vals : [] }); rerender(); },
