  asCamp: t => { App.ui.asCamp = t.dataset.k; rerender(); },
  asLabels: t => { const rows = (App.tables.asReg || { rows: [] }).rows.slice(0, 60); if (!rows.length || !rows[0].tag) return toast('No assets to print.', 'bad'); modal(`Asset labels (${rows.length})`, `<div class="as-labels">${rows.map(asLabel).join('')}</div><p class="small muted">Print this sheet on label stock; each label carries the QR code, barcode, tag, asset name and location. Bulk RFID encoding is done from the label printer utility.</p>`, `<button class="btn" data-act="closeModal">Close</button><button class="btn" data-act="asLabelsPdf">Download labels (PDF)</button><button class="btn primary" data-act="asLabelsPrint">Print labels</button>`, true); },
