  let R; try { R = def[2](); } catch (e) { console.error(e); return `<div class="note bad">${esc(e.message)}</div>`; }
  const f = App.ui.asRF || {}; let rows = R.rows; if (f.cat) rows = rows.filter(r => { const a = r.cat && r.id ? r : r.a || asAsset(r.asset) || null; return !a || a.cat === f.cat; }); if (f.st) rows = rows.filter(r => { const a = r.status && r.id && r.tag ? r : r.a || asAsset(r.asset) || null; return !a || a.status === f.st; }); if (f.from || f.to) rows = rows.filter(r => { const d = r.purchaseDate || r.date || (r.createdAt || '').slice(0, 10) || (r.h ? r.h.at.slice(0, 10) : '') || (r.r && r.r.at ? r.r.at.slice(0, 10) : ''); return !d || ((!f.from || d >= f.from) && (!f.to || d <= f.to)); });
  const NOSUM = /days|rating|visits|assets$|^assets|downtime/i, totalVals = rows.length ? R.cols.map(c => ['inr', 'num'].includes(c.t) && !NOSUM.test(c.h) ? rows.reduce((s, r) => { let x; try { x = c.x ? c.x(r) : c.k(r); } catch (e) { x = 0; } return s + (typeof x === 'number' && isFinite(x) ? x : 0); }, 0) : null) : null;
