  return `<div class="srf-strip2">${pick}<span class="grow"></span><span class="small">${rows.length} rows · business type, region, zone and branch from the filter bar</span></div>${card(def[1], table('asRep', R.cols, rows, { totalVals, compact: true, title: def[1], limit: 150, empty: 'No records for this report and the selected filters.' }), { right: exportBtns('asRep', 'as_reports') })}`;
